package plan

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync"

	"github.com/PurdueBlueTeam/phylax/internal/link"
)

// The agent configuration (which modules run and with what settings) is
// generated by the controller per host from the manifest, signed with the
// plan key and sent in `welcome` and as `config` messages. Like steps and
// controls it is host-bound, carries the controller epoch and is replay
// protected: the agent accepts only a (epoch, version) above its durable mark.
// The signature covers the canonical (RFC 8785 subset) encoding of the whole
// body, so a relay or a disk tamperer cannot alter a setting.

const (
	configDomain = "phylax-config-v1\x00"
	configV      = 1
)

// MaxConfigBody bounds an accepted config body (rules included).
const MaxConfigBody = 3 << 20

// Config errors beyond the shared step errors.
var (
	// ErrConfigCurrent means the config is exactly the one already applied.
	ErrConfigCurrent = errors.New("config: already applied")
)

// ModuleLimits is a module's event rate budget. Zero means the agent's default.
type ModuleLimits struct {
	RatePerSec int `json:"rate_per_sec,omitempty"`
	Burst      int `json:"burst,omitempty"`
}

// HealthSettings configures the health module.
type HealthSettings struct {
	ModuleLimits
	IntervalSec int `json:"interval_sec,omitempty"`
}

// AuditSettings configures the Linux audit module.
type AuditSettings struct {
	ModuleLimits
	// WebRoots are content roots (service content roots and upload dirs):
	// watched recursively and swept.
	WebRoots []string `json:"web_roots,omitempty"`
	// ServiceBinaries are the declared binaries of the host's services,
	// watched like persistence paths.
	ServiceBinaries  []string `json:"service_binaries,omitempty"`
	ExtraWatches     []string `json:"extra_watches,omitempty"`
	NetRules         bool     `json:"net_rules,omitempty"`
	SweepIntervalSec int      `json:"sweep_interval_sec,omitempty"`
}

// CanarySettings is one egress canary probe target.
type CanarySettings struct {
	Addr string `json:"addr"`
	Port uint16 `json:"port"`
	Tag  string `json:"tag,omitempty"`
}

// NetSettings configures the network module.
type NetSettings struct {
	ModuleLimits
	// Services maps "proto/port" to a service name.
	Services    map[string]string `json:"services,omitempty"`
	NFLogGroups []uint16          `json:"nflog_groups,omitempty"`
	Canaries    []CanarySettings  `json:"canaries,omitempty"`
	HashExe     bool              `json:"hash_exe,omitempty"`
	IntervalMS  int               `json:"interval_ms,omitempty"`
}

// WinChannel is one Windows event log channel subscription.
type WinChannel struct {
	Name    string `json:"name"`
	Include []int  `json:"include,omitempty"`
	All     bool   `json:"all,omitempty"`
	Exclude []int  `json:"exclude,omitempty"`
}

// WinevtSettings configures the Windows event log module. No channels means
// the module's built-in defaults.
type WinevtSettings struct {
	ModuleLimits
	Channels    []WinChannel `json:"channels,omitempty"`
	SysmonHints []string     `json:"sysmon_hints,omitempty"`
}

// PinSettings ties a scored service to the binary it must run.
type PinSettings struct {
	Service string `json:"service"`
	Path    string `json:"path"`
	Unit    string `json:"unit,omitempty"`
}

// LedgerRef names the reference ledger the integrity module judges against.
// The ledger file travels separately (it is large); the config pins its hash.
type LedgerRef struct {
	// File is relative to the agent state directory (default "ledger.plx").
	File   string `json:"file,omitempty"`
	SHA256 string `json:"sha256,omitempty"`
}

// IntegritySettings configures the integrity module.
type IntegritySettings struct {
	ModuleLimits
	Pins             []PinSettings `json:"pins,omitempty"`
	SweepRoots       []string      `json:"sweep_roots,omitempty"`
	SweepIntervalSec int           `json:"sweep_interval_sec,omitempty"`
	PinIntervalSec   int           `json:"pin_interval_sec,omitempty"`
	Ledger           LedgerRef     `json:"ledger"`
}

// RuleFile is one detection rule document stream (YAML text).
type RuleFile struct {
	Name string `json:"name"`
	YAML string `json:"yaml"`
}

// ProfileSeed fills a rule profile from the manifest (detect.Engine.Seed).
type ProfileSeed struct {
	Profile string   `json:"profile"`
	Key     []string `json:"key,omitempty"`
	Values  []string `json:"values"`
}

// DetectSettings configures local detection.
type DetectSettings struct {
	ModuleLimits
	Rules []RuleFile `json:"rules,omitempty"`
	// Seeds are the manifest-derived static profiles (scored accounts,
	// service comms, declared dependencies, ...), the behavioural scorer
	// exemption: rules exempt by account/behaviour, never by address.
	Seeds []ProfileSeed `json:"seeds,omitempty"`
	// ActEnabled allows rules in mode "act" to trigger tier-0 responses. The
	// controller leaves it false: alerts only, until a later task.
	ActEnabled bool `json:"act_enabled,omitempty"`
	MaxKeys    int  `json:"max_keys,omitempty"`
}

// ModuleSettings holds one optional section per module; a nil section means
// the module does not run on this host.
type ModuleSettings struct {
	Health    *HealthSettings    `json:"health,omitempty"`
	Audit     *AuditSettings     `json:"audit,omitempty"`
	Net       *NetSettings       `json:"net,omitempty"`
	Winevt    *WinevtSettings    `json:"winevt,omitempty"`
	Integrity *IntegritySettings `json:"integrity,omitempty"`
	Detect    *DetectSettings    `json:"detect,omitempty"`
}

// Budgets are agent-wide resource budgets.
type Budgets struct {
	MemoryLimitMB int `json:"memory_limit_mb,omitempty"`
}

// AgentConfig is the typed per-host configuration.
type AgentConfig struct {
	V        int    `json:"v"`
	Host     string `json:"host"`
	Epoch    uint64 `json:"epoch"`
	Version  uint64 `json:"version"`
	IssuedAt int64  `json:"issued_at"`
	// Roles are the manifest roles with shorthands expanded (vantage becomes
	// check_runner, scanner, canary).
	Roles   []string       `json:"roles,omitempty"`
	Modules ModuleSettings `json:"modules"`
	Budgets Budgets        `json:"budgets"`
}

// HasRole reports whether the host holds role.
func (c *AgentConfig) HasRole(role string) bool {
	for _, r := range c.Roles {
		if r == role {
			return true
		}
	}
	return false
}

// Digest identifies the whole signed content.
func (c *AgentConfig) Digest() (string, error) {
	raw, err := json.Marshal(c)
	if err != nil {
		return "", err
	}
	canon, err := Canonicalize(raw)
	if err != nil {
		return "", err
	}
	h := sha256.Sum256(canon)
	return hex.EncodeToString(h[:]), nil
}

func configSigningBytes(canonBody []byte) []byte { return append([]byte(configDomain), canonBody...) }

// SignConfig signs c (whose Host, Epoch and Version must be set) and returns
// the wire message. Body is the canonical encoding, Sig is hex.
func SignConfig(key ed25519.PrivateKey, c *AgentConfig) (*link.Config, error) {
	if len(key) != ed25519.PrivateKeySize {
		return nil, errors.New("config: signer not configured")
	}
	if c.Host == "" || c.Version == 0 {
		return nil, errors.New("config: host and version are required")
	}
	c.V = configV
	raw, err := json.Marshal(c)
	if err != nil {
		return nil, err
	}
	canon, err := Canonicalize(raw)
	if err != nil {
		return nil, err
	}
	if len(canon) > MaxConfigBody {
		return nil, fmt.Errorf("config: body of %d bytes exceeds %d", len(canon), MaxConfigBody)
	}
	sig := ed25519.Sign(key, configSigningBytes(canon))
	return &link.Config{Version: c.Version, Epoch: c.Epoch, Body: canon, Sig: hex.EncodeToString(sig)}, nil
}

// ConfigVerifier is the agent-side config checker.
type ConfigVerifier struct {
	Key    ed25519.PublicKey
	HostID string
	// Store is the durable (epoch, version) high-water mark of configs
	// accepted. Mark.Seq holds the version.
	Store SeqStore

	mu      sync.Mutex
	applied Mark
	digest  string
}

// MarkApplied records that the config (epoch, version) with this body digest
// is now applied and persisted; a resend of exactly it is then ErrConfigCurrent.
func (v *ConfigVerifier) MarkApplied(epoch, version uint64, digest string) {
	v.mu.Lock()
	v.applied, v.digest = Mark{epoch, version}, digest
	v.mu.Unlock()
}

// Parse checks the signature, version, host binding and field consistency of
// a config without touching the replay mark. Used at start-up for the
// persisted config, and by Verify.
func (v *ConfigVerifier) Parse(w *link.Config) (*AgentConfig, error) {
	if len(v.Key) != ed25519.PublicKeySize {
		return nil, &StepError{ErrNoKey, ""}
	}
	if v.HostID == "" {
		return nil, &StepError{ErrNoHost, ""}
	}
	if w == nil || len(w.Body) == 0 || len(w.Body) > MaxConfigBody {
		return nil, &StepError{ErrMalformed, "missing or oversized body"}
	}
	sig, err := hex.DecodeString(w.Sig)
	if err != nil || len(sig) != ed25519.SignatureSize {
		return nil, &StepError{ErrBadSignature, "missing or malformed signature"}
	}
	canon, err := Canonicalize(w.Body)
	if err != nil {
		return nil, &StepError{ErrMalformed, err.Error()}
	}
	if !ed25519.Verify(v.Key, configSigningBytes(canon), sig) {
		return nil, &StepError{ErrBadSignature, ""}
	}
	var c AgentConfig
	if err := json.Unmarshal(canon, &c); err != nil {
		return nil, &StepError{ErrMalformed, err.Error()}
	}
	switch {
	case c.V != configV:
		return nil, &StepError{ErrMalformed, fmt.Sprintf("config version %d", c.V)}
	case c.Host != v.HostID:
		return nil, &StepError{ErrWrongHost, fmt.Sprintf("config for %q", c.Host)}
	case c.Version == 0 || c.Version > maxSafe || c.Epoch > maxSafe:
		return nil, &StepError{ErrMalformed, "epoch/version out of range"}
	case c.Version != w.Version || c.Epoch != w.Epoch:
		return nil, &StepError{ErrMalformed, "envelope epoch/version differ from the signed body"}
	}
	return &c, nil
}

// Verify is Parse plus replay protection. On success the mark is durable
// before it returns, so a config that verifies is accepted at most once, except
// that the very config whose acceptance was interrupted before it was applied
// may be presented again. ErrConfigCurrent means w is the config already in force.
func (v *ConfigVerifier) Verify(w *link.Config) (*AgentConfig, error) {
	c, err := v.Parse(w)
	if err != nil {
		return nil, err
	}
	if v.Store == nil {
		return nil, &StepError{ErrNoStore, ""}
	}
	dg, err := c.Digest()
	if err != nil {
		return nil, &StepError{ErrMalformed, err.Error()}
	}
	got := Mark{c.Epoch, c.Version}
	v.mu.Lock()
	defer v.mu.Unlock()
	if v.applied == got && v.digest == dg {
		return c, ErrConfigCurrent
	}
	last, err := v.Store.Load()
	if err != nil {
		return nil, &StepError{ErrStore, err.Error()}
	}
	if got.Epoch < last.Epoch {
		return nil, &StepError{ErrStaleEpoch, fmt.Sprintf("%d < %d", got.Epoch, last.Epoch)}
	}
	if got.Less(last) || (got == last && v.applied == got) {
		return nil, &StepError{ErrReplay, fmt.Sprintf("(%d,%d) <= (%d,%d)", got.Epoch, got.Seq, last.Epoch, last.Seq)}
	}
	if err := v.Store.Save(got); err != nil {
		return nil, &StepError{ErrStore, err.Error()}
	}
	return c, nil
}

// RuleStream joins the rule files into one multi-document YAML stream (the
// detect loader needs every file at once: profiles declared in one file are
// used by rules in another). Files are separated by document markers; a
// leading or trailing marker in a file is dropped so no empty document results.
func (d *DetectSettings) RuleStream() []byte {
	var b []byte
	for _, f := range d.Rules {
		y := strings.TrimSpace(f.YAML)
		for strings.HasPrefix(y, "---") {
			y = strings.TrimSpace(strings.TrimPrefix(y, "---"))
		}
		for strings.HasSuffix(y, "\n---") {
			y = strings.TrimSpace(strings.TrimSuffix(y, "---"))
		}
		if y == "" {
			continue
		}
		b = append(b, "---\n# "...)
		b = append(b, strings.NewReplacer("\n", " ", "\r", " ").Replace(f.Name)...)
		b = append(b, '\n')
		b = append(b, y...)
		b = append(b, '\n')
	}
	return b
}
